from collections import deque

def bfs_shortest_path(graph, start, end):
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, dist = queue.popleft()
        if current == end:
            return dist
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return float('inf')

def one_letter_diff(word1, word2):
    diff_count = sum(c1 != c2 for c1, c2 in zip(word1, word2))
    return diff_count == 1

def find_best_word_to_add(dictionary, start, end):
    n = len(dictionary)
    word_length = len(start)

    # Create a graph where each word points to words that differ by one letter
    graph = {word: [] for word in dictionary}
    for i in range(n):
        for j in range(i + 1, n):
            if one_letter_diff(dictionary[i], dictionary[j]):
                graph[dictionary[i]].append(dictionary[j])
                graph[dictionary[j]].append(dictionary[i])

    # Find the shortest path without adding any new word
    original_min_steps = bfs_shortest_path(graph, start, end)

    # Generate all possible one-letter transformations of start and end
    possible_new_words = set()
    for word in [start, end]:
        for i in range(word_length):
            for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                if c != word[i]:
                    new_word = word[:i] + c + word[i+1:]
                    possible_new_words.add(new_word)

    best_word = None
    best_steps = float('inf')

    for new_word in possible_new_words:
        if new_word in dictionary:
            continue

        # Add the new word to the graph
        new_graph = graph.copy()
        new_graph[new_word] = []
        for existing_word in dictionary:
            if one_letter_diff(new_word, existing_word):
                new_graph[new_word].append(existing_word)
                new_graph[existing_word].append(new_word)

        # Find the shortest path with the new word
        new_min_steps = bfs_shortest_path(new_graph, start, end)

        if new_min_steps < best_steps or (new_min_steps == best_steps and (best_word is None or new_word < best_word)):
            best_word = new_word
            best_steps = new_min_steps

    if best_word is None or best_steps >= original_min_steps:
        return "0", -1 if original_min_steps == float('inf') else original_min_steps
    else:
        return best_word, best_steps

